using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
namespace HDRemix.LunaCosmetics {
    internal static class SwapTests {
        static readonly List<string> passed=new List<string>();
        static void Check(bool yes,string text){if(!yes)throw new Exception(text);}
        static void Test(string name,Action work){work();passed.Add(name);Console.WriteLine("PASS "+name);}
        static void Refuses(Action work,string text){try{work();}catch(Exception e){Check(e.Message.IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0,"Unexpected refusal: "+e);return;}throw new Exception("Expected refusal: "+text);}
        static byte[] Hex(string s){return Enumerable.Range(0,s.Length/2).Select(i=>Convert.ToByte(s.Substring(i*2,2),16)).ToArray();}
        static string At(string root,string rel){return Path.Combine(root,rel.Replace('/',Path.DirectorySeparatorChar));}
        static int Field(byte[] data,StratagemSwaps.Row row,SwapField f){return f.payload?row.block.payload+checked((int)SemanticEditor.U64(data,row.at+152)):row.at+f.offset;}
        // Old swap synthesis is fixture code only; this file is excluded from the release EXE.
        static byte[] Legacy(byte[] input,int mask){var b=GameBox.Decrypt(input);var changed=(byte[])b.Clone();var blocks=StratagemSwaps.Blocks(b);var rows=StratagemSwaps.Rows(b,blocks);foreach(var s in StratagemSwaps.Catalog.swaps)if((mask&s.bit)!=0)foreach(var f in s.fields){var bytes=Hex(f.after);Buffer.BlockCopy(bytes,0,changed,Field(b,rows[s.source],f),bytes.Length);}var output=SemanticEditor.Finish(b,changed,blocks.Last());return output==null?input:GameBox.Encrypt(output);}
        static void Original(byte[] b){var rows=StratagemSwaps.Rows(b,StratagemSwaps.Blocks(b));foreach(var s in StratagemSwaps.Catalog.swaps)foreach(var f in s.fields)Check(b.Skip(Field(b,rows[s.source],f)).Take(f.bytes).SequenceEqual(Hex(f.before)),"Legacy field remains: "+s.name+" "+f.label);}
        static void Preserved(byte[] before,byte[] after){var rows=StratagemSwaps.Rows(before,StratagemSwaps.Blocks(before));var allowed=new HashSet<int>();foreach(var s in StratagemSwaps.Catalog.swaps)foreach(var f in s.fields){int at=Field(before,rows[s.source],f);for(int i=0;i<f.bytes;i++)allowed.Add(at+i);}int header=StratagemSwaps.Blocks(before).Last().header;for(int i=0;i<4;i++)allowed.Add(header+12+i);Check(after.Length>=before.Length&&after.Length<=before.Length+15,"Cleanup size");for(int i=0;i<before.Length;i++)Check(before[i]==after[i]||allowed.Contains(i),"Unrelated data changed at "+i);Check(SemanticEditor.Murmur(before)==SemanticEditor.Murmur(after),"Resource hash changed");}
        internal static string[] Run(string dir,Catalog c){
            byte[] input=File.ReadAllBytes(Path.Combine(dir,"stratagem.bin")),plain=GameBox.Decrypt(input),both=Legacy(input,768);string stage=Path.Combine(dir,"dummy_game"),direct=Path.Combine(dir,"game-copy");var core=new ExportCore(c);Action<int,string> progress=delegate{};
            Action<string> reset=root=>{File.WriteAllBytes(At(root,ExportCore.RelativeTarget),File.ReadAllBytes(Path.Combine(dir,"stock-armor.bin")));File.WriteAllBytes(At(root,ExportCore.EntityTarget),File.ReadAllBytes(Path.Combine(dir,"stock-entity.bin")));File.WriteAllBytes(At(root,ExportCore.StratagemTarget),both);};
            Test("retired FRV and Dark Fluid enable masks are rejected by CLI and export",delegate{foreach(int mask in new[]{256,512,768,895,1919}){Refuses(()=>Program.Options.Parse(new[]{"--mask",mask.ToString()}),"invalid");Refuses(()=>core.Export(stage,mask,progress),"invalid");}Check((Program.Options.Parse(new string[0]).mask&768)==0,"Retired defaults");});
            Test("normal stratagem file remains byte-identical",delegate{Check(StratagemSwaps.Restore(input).SequenceEqual(input),"Normal file changed");});
            Test("each old swap combination is removed with unrelated bytes and identities preserved",delegate{foreach(int mask in new[]{256,512,768}){var before=Legacy(input,mask);var after=StratagemSwaps.Restore(before);Original(GameBox.Decrypt(after));Preserved(GameBox.Decrypt(before),GameBox.Decrypt(after));Check(StratagemSwaps.Restore(after).SequenceEqual(after),"Cleanup not idempotent");}File.WriteAllBytes(Path.Combine(dir,"legacy-swaps-both.bin"),both);File.WriteAllBytes(Path.Combine(dir,"legacy-swaps-cleaned.bin"),StratagemSwaps.Restore(both));});
            Test("actual installed stratagem snapshot is cleaned without erasing unrelated tuning",delegate{var before=File.ReadAllBytes(Path.Combine(dir,"live-stratagem.bin"));var after=StratagemSwaps.Restore(before);Original(GameBox.Decrypt(after));Preserved(GameBox.Decrypt(before),GameBox.Decrypt(after));File.WriteAllBytes(Path.Combine(dir,"live-stratagem-cleaned.bin"),after);});
            Test("partial recognized swaps clean while unfamiliar icons and cooldowns survive",delegate{var b=GameBox.Decrypt(both);var row=StratagemSwaps.Rows(b,StratagemSwaps.Blocks(b))[3935317067];Buffer.BlockCopy(BitConverter.GetBytes(0x1122334455667788UL),0,b,row.at+176,8);Buffer.BlockCopy(BitConverter.GetBytes(123.0f),0,b,row.at+104,4);var after=GameBox.Decrypt(StratagemSwaps.Restore(GameBox.Encrypt(b)));Check(SemanticEditor.U64(after,row.at+176)==0x1122334455667788UL&&BitConverter.ToSingle(after,row.at+104)==123.0f,"Custom edits erased");Check(SemanticEditor.U64(after,row.at+168)==0x0bdf199f7ac14f43UL,"Legacy package retained");Preserved(b,after);});
            Test("unknown structural overlap stops all resources before export",delegate{reset(stage);var b=GameBox.Decrypt(both);var row=StratagemSwaps.Rows(b,StratagemSwaps.Blocks(b))[3935317067];Buffer.BlockCopy(BitConverter.GetBytes(0x1122334455667788UL),0,b,row.at+168,8);File.WriteAllBytes(At(stage,ExportCore.StratagemTarget),GameBox.Encrypt(b));var hashes=StandaloneCore.Targets.Select(t=>ExportCore.FileHash(At(stage,t))).ToArray();Refuses(()=>core.Export(stage,127,progress),"safely remove");Check(StandaloneCore.Targets.Select(t=>ExportCore.FileHash(At(stage,t))).SequenceEqual(hashes),"Conflict wrote data");});
            Test("Luna cleanup supports leave-ship mode without touching normal resources",delegate{reset(stage);var entity=File.ReadAllBytes(At(stage,ExportCore.EntityTarget));core.Export(stage,191,progress,true);Original(GameBox.Decrypt(File.ReadAllBytes(At(stage,ExportCore.StratagemTarget))));Check(File.ReadAllBytes(At(stage,ExportCore.EntityTarget)).SequenceEqual(entity),"Leave ship changed entity");string hash=ExportCore.FileHash(At(stage,ExportCore.StratagemTarget));core.Export(stage,191,progress,true);Check(ExportCore.FileHash(At(stage,ExportCore.StratagemTarget))==hash,"No-op stratagem resealed");Check((core.DetectMask(stage)&768)==0,"Retired mask detected");});
            Test("three-resource Luna cleanup failure rolls back exact inputs",delegate{reset(stage);var hashes=StandaloneCore.Targets.Select(t=>ExportCore.FileHash(At(stage,t))).ToArray();core.AfterCommitForTest=n=>{if(n==3)throw new IOException("third commit test");};try{Refuses(()=>core.Export(stage,127,progress,true),"third commit");}finally{core.AfterCommitForTest=null;}Check(StandaloneCore.Targets.Select(t=>ExportCore.FileHash(At(stage,t))).SequenceEqual(hashes),"Cleanup rollback failed");});
            Test("standalone cleanup backs up all resources and preserves exact restore semantics",delegate{reset(direct);var hashes=StandaloneCore.Targets.Select(t=>ExportCore.FileHash(At(direct,t))).ToArray();var d=new StandaloneCore(c,core,Path.Combine(dir,"cleanup-store"),()=>false,Path.Combine(dir,"empty-legacy"));d.Install(direct,127,progress);Original(GameBox.Decrypt(File.ReadAllBytes(At(direct,ExportCore.StratagemTarget))));Check(d.DetectMask(direct)==127,"Removed options leaked into detection");d.Restore(direct,progress);Check(StandaloneCore.Targets.Select(t=>ExportCore.FileHash(At(direct,t))).SequenceEqual(hashes),"Exact previous-file restore failed");});
            Test("standalone third-resource failure recovers cleanup transaction",delegate{reset(direct);var hashes=StandaloneCore.Targets.Select(t=>ExportCore.FileHash(At(direct,t))).ToArray();var d=new StandaloneCore(c,core,Path.Combine(dir,"cleanup-rollback-store"),()=>false,Path.Combine(dir,"empty-legacy"));d.AfterCommitForTest=n=>{if(n==3)throw new IOException("cleanup commit failure");};Refuses(()=>d.Install(direct,127,progress),"cleanup commit");Check(StandaloneCore.Targets.Select(t=>ExportCore.FileHash(At(direct,t))).SequenceEqual(hashes),"Standalone cleanup rollback failed");});
            return passed.ToArray();
        }
    }
}
